<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { batchApi, genTypeApi, generationTypeConfigApi, imageProviderApi, promptApi, settingsApi, taskApi, type ImageProvider } from '@/api/modules'
import { connectWs, onWsEvent } from '@/ws/client'
import GlassCard from '@/v2/components/GlassCard.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import V2Field from '@/v2/components/V2Field.vue'
import type { GenerationConfig, ParameterConfig, RuntimeWorkflow } from '@/v2/features/generation-config/model'
import { activeStatuses, statusMeta, type TaskOutput } from '@/v2/features/tasks/model'
import { useTaskOutputThumbs } from '@/v2/features/tasks/useTaskOutputThumbs'
import MediaParameterField from './MediaParameterField.vue'

type GenerationType = { id:number; code:string; name:string; media_type:'image'|'video'|'audio'; default_workflow_id:number|null; param_template:ParameterConfig[] }
type Row = { localId:number; params:Record<string,any>; paramCache:Record<string,Record<string,any>>; workflowVersionId:number|null; taskId:number|null; batchId:number|null; status:string; error:string|null; outputs:Array<TaskOutput&{thumbUrl?:string}> }
type SelectSetting = { label:string; options:Array<{label:string;value:any}>; default_value:any }

const route=useRoute();const router=useRouter();const loading=ref(true);const submitting=ref(false);const notice=ref('');const typeInfo=ref<GenerationType|null>(null);const config=ref<GenerationConfig|null>(null);const published=ref<number|null>(null);const runtimeWorkflows=ref<RuntimeWorkflow[]>([]);const imageProviders=ref<ImageProvider[]>([]);const executionTarget=ref('comfyui');const settings=ref<Record<string,SelectSetting>>({});const rows=ref<Row[]>([]);const batchName=ref('');const importMode=ref<'append'|'replace'>('append');const importInput=ref<HTMLInputElement|null>(null);const preview=ref<TaskOutput|null>(null);let localId=0;let pollTimer:ReturnType<typeof setInterval>|null=null;let draftTimer:ReturnType<typeof setTimeout>|null=null;let offWs:(()=>void)|null=null;let draftReady=false;let activeDraftCode=''
const code=computed(()=>String(route.params.code||''));const isMotion=computed(()=>code.value==='motion_transfer');const title=computed(()=>config.value?.page?.title||typeInfo.value?.name||'创作生成');const description=computed(()=>config.value?.page?.description||'按行配置参数，支持单项或批量提交。');const busy=computed(()=>rows.value.some(r=>activeStatuses.includes(r.status)))
const defaultWorkflowVersion=computed(()=>runtimeWorkflows.value.find(v=>v.is_default)?.workflow_version_id||runtimeWorkflows.value[0]?.workflow_version_id||null)
const sizeSetting=computed(()=>settings.value[typeInfo.value?.media_type==='video'?'video_size':'image_size'])
const outputMediaType=computed(()=>typeInfo.value?.media_type||'image')
const usingGemini=computed(()=>code.value==='mixed'&&executionTarget.value.startsWith('gemini:'))
const geminiProviderId=computed(()=>usingGemini.value?Number(executionTarget.value.split(':')[1]):null)
const {withThumbs,release}=useTaskOutputThumbs()

function randomSeed(){return Math.floor(Math.random()*4294967295)}
function maintainedImageSize(){return String(settings.value.image_size?.default_value||settings.value.image_size?.options?.[0]?.value||'')}
function workflowFor(versionId:number|null){return runtimeWorkflows.value.find(v=>v.workflow_version_id===versionId)||null}
function parametersFor(row:Row){return workflowFor(row.workflowVersionId)?.parameters||[]}
function schemesFor(row:Row){return workflowFor(row.workflowVersionId)?.parameter_schemes||[]}
function visibleParameters(row:Row){return parametersFor(row).filter(p=>{if(isMotion.value&&(p.key==='prompt'||p.key==='duration'))return false;if(p.key==='width'||p.key==='height')return false;return true})}
function hasSize(row:Row){const schema=parametersFor(row);return schema.some(p=>p.key==='width')&&schema.some(p=>p.key==='height')}
function defaultParams(versionId:number|null){const value:Record<string,any>={};const schema=workflowFor(versionId)?.parameters||[];for(const p of schema)value[p.key]=p.type==='seed'?randomSeed():(p.default??settings.value[p.options_from||'']?.default_value??(p.type==='bool'?false:null));const size=sizeSetting.value?.default_value;if(size&&schema.some(p=>p.key==='width')&&schema.some(p=>p.key==='height')){const [w,h]=String(size).split('x').map(Number);value.width=w;value.height=h;value.__size=size}const workflowSchemes=workflowFor(versionId)?.parameter_schemes||[];const scheme=workflowSchemes.find(v=>v.is_default)||workflowSchemes[0];if(isMotion.value&&scheme){value.__scheme=scheme.id;Object.assign(value,scheme.params)}return value}
function makeRow():Row{const versionId=usingGemini.value?null:defaultWorkflowVersion.value;return{localId:++localId,params:usingGemini.value?{prompt:'',reference_resource_ids:[],size:maintainedImageSize()}:defaultParams(versionId),paramCache:{},workflowVersionId:versionId,taskId:null,batchId:null,status:'DRAFT',error:null,outputs:[]}}
function addRow(){rows.value.unshift(makeRow())}
function draftKey(target=activeDraftCode||code.value){return `v2-generate-draft:${target}`}
function saveLocalDraft(){if(!draftReady||!activeDraftCode)return;const savedRows=rows.value.map(row=>({...row,outputs:[]}));sessionStorage.setItem(draftKey(),JSON.stringify({batchName:batchName.value,importMode:importMode.value,executionTarget:executionTarget.value,rows:savedRows,savedAt:Date.now()}))}
function restoreLocalDraft(){try{const raw=sessionStorage.getItem(draftKey());if(!raw)return false;const saved=JSON.parse(raw);if(!Array.isArray(saved.rows)||!saved.rows.length)return false;if(saved.executionTarget==='comfyui'||imageProviders.value.some(v=>`gemini:${v.id}`===saved.executionTarget))executionTarget.value=saved.executionTarget;rows.value=saved.rows.map((row:any)=>{const versionId=usingGemini.value?null:(runtimeWorkflows.value.some(v=>v.workflow_version_id===row.workflowVersionId)?row.workflowVersionId:defaultWorkflowVersion.value);const params=row.params||(usingGemini.value?{prompt:'',reference_resource_ids:[],size:maintainedImageSize()}:defaultParams(versionId));if(usingGemini.value&&!settings.value.image_size?.options?.some(option=>String(option.value)===String(params.size)))params.size=maintainedImageSize();return{...row,localId:++localId,workflowVersionId:versionId,params,paramCache:row.paramCache||{},outputs:[]}});batchName.value=String(saved.batchName||'');importMode.value=saved.importMode==='replace'?'replace':'append';if(rows.value.some(row=>row.taskId&&activeStatuses.includes(row.status)))startPoll();notice.value='已恢复刷新前未完成的页面数据';return true}catch{return false}}
function cloneRow(row:Row){const next=makeRow();next.params=JSON.parse(JSON.stringify(row.params));next.paramCache=JSON.parse(JSON.stringify(row.paramCache));next.workflowVersionId=row.workflowVersionId;rows.value.push(next)}
function removeRow(index:number){if(rows.value.length===1){rows.value=[makeRow()];return}rows.value.splice(index,1)}
function optionList(p:ParameterConfig){return p.options||settings.value[p.options_from||'']?.options||[]}
function visible(p:ParameterConfig,row:Row){const rule=p.visible_when;if(rule){const v=row.params[rule.key];if(rule.operator==='truthy'&&!v)return false;if(rule.operator==='equals'&&v!==rule.value)return false;if(rule.operator==='not_equals'&&v===rule.value)return false}const match=p.key.match(/^reference_image_(\d)$/);if(match)return Boolean(row.params.multi_reference_enabled)&&Number(match[1])<=Number(row.params.multi_reference_count||1);return true}
function setSize(row:Row,value:string){row.params.__size=value;const [w,h]=String(value).split('x').map(Number);row.params.width=w;row.params.height=h}
function switchWorkflow(row:Row,value:any){const nextId=Number(value)||null;if(nextId===row.workflowVersionId)return;const previousId=row.workflowVersionId;const previousParams=JSON.parse(JSON.stringify(row.params));if(previousId)row.paramCache[String(previousId)]=previousParams;const next=defaultParams(nextId);const nextSchema=workflowFor(nextId)?.parameters||[];const oldSchema=parametersFor(row);const oldByKey=new Map(oldSchema.map(item=>[item.key,item]));const usedOldKeys=new Set<string>();for(const parameter of nextSchema){const old=oldByKey.get(parameter.key);if(old&&old.type===parameter.type&&previousParams[parameter.key]!==undefined){next[parameter.key]=previousParams[parameter.key];usedOldKeys.add(parameter.key);continue}// 按类型匹配媒体参数（key 不同但类型相同的图片/视频/音频参数）
  if(['image','video','audio'].includes(parameter.type)){const oldByType=oldSchema.find(item=>item.type===parameter.type&&!usedOldKeys.has(item.key)&&previousParams[item.key]!==undefined&&previousParams[item.key]!==null);if(oldByType){next[parameter.key]=previousParams[oldByType.key];usedOldKeys.add(oldByType.key);// 同时迁移 __mask 字段
    const oldMaskKey=`${oldByType.key}__mask`;if(previousParams[oldMaskKey]!==undefined&&previousParams[oldMaskKey]!==null){next[`${parameter.key}__mask`]=previousParams[oldMaskKey]}}}}Object.assign(next,row.paramCache[String(nextId)]||{});row.workflowVersionId=nextId;row.params=next}
function applyScheme(row:Row,id:any){row.params.__scheme=id;const scheme=schemesFor(row).find(v=>String(v.id)===String(id));if(scheme)Object.assign(row.params,scheme.params)}
function assetContext(){const projectId=Number(route.query.project_id),entityId=Number(route.query.entity_id),entityType=String(route.query.entity_type||'');return projectId&&entityId&&entityType?{__asset_context:{project_id:projectId,entity_type:entityType,entity_id:entityId}}:{}}
function cleanParams(row:Row){if(usingGemini.value)return{prompt:String(row.params.prompt||'').trim(),reference_resource_ids:Array.isArray(row.params.reference_resource_ids)?row.params.reference_resource_ids.filter(Boolean):[],size:String(row.params.size||maintainedImageSize()),__execution_provider:'gemini_image',__provider_config_id:geminiProviderId.value,...assetContext()};const result:Record<string,any>={};const schemaKeys=new Set(parametersFor(row).map(p=>p.key));for(const parameter of parametersFor(row)){const value=row.params[parameter.key];if(value!==null&&value!==''&&value!==undefined)result[parameter.key]=value}for(const key of Object.keys(row.params)){if(key.endsWith('__mask')&&row.params[key]){const baseKey=key.slice(0,-6);if(schemaKeys.has(baseKey)&&row.params[key]!==null&&row.params[key]!==undefined)result[key]=row.params[key]}}return result}
function validate(row:Row){if(usingGemini.value){if(!geminiProviderId.value)return '请选择 Gemini Image 提供方';if(!settings.value.image_size?.options?.some(option=>String(option.value)===String(row.params.size)))return '请选择维护项中的图片尺寸';if(!String(row.params.prompt||'').trim())return '请填写图片提示词';return ''}if(!row.workflowVersionId)return '没有可用工作流';for(const p of parametersFor(row)){if(!visible(p,row))continue;if(p.required&&(row.params[p.key]===null||row.params[p.key]===undefined||row.params[p.key]===''))return `请填写${p.label}`}return ''}
function findPrompt(row:Row){const parameter=parametersFor(row).find(p=>['text','textarea'].includes(p.type)&&p.key.toLowerCase().includes('prompt')&&!p.key.toLowerCase().includes('negative'));return parameter?row.params[parameter.key]:''}
function findImages(row:Row){return parametersFor(row).filter(p=>p.type==='image').map(p=>row.params[p.key]).flat().filter(Boolean)}
function switchExecutionTarget(){rows.value=rows.value.map(old=>{const prompt=old.params.prompt||findPrompt(old)||'';const refs=old.params.reference_resource_ids||findImages(old);const next=makeRow();next.params.prompt=prompt;if(usingGemini.value)next.params.reference_resource_ids=Array.isArray(refs)?refs:refs?[refs]:[];return next});notice.value=usingGemini.value?'已切换到 Gemini Image：无参考图为生图，有参考图为改图。':'已切换到 ComfyUI 工作流。'}
function errorText(e:any){return e?.response?.data?.detail||e?.response?.data?.message||e?.message||'操作失败'}
const savingPromptKey=ref<string|null>(null)
async function saveToPromptLib(row:Row,parameter:ParameterConfig){
  const text=String(row.params[parameter.key]||'').trim()
  if(!text){notice.value='提示词内容为空';return}
  const isNegative=parameter.key.toLowerCase().includes('negative')
  savingPromptKey.value=parameter.key
  try{
    // 获取或创建分类（按媒体类型）
    const mt=outputMediaType.value
    const mediaLabel=mt==='video'?'视频':mt==='audio'?'音频':'图片'
    const categoryName=`${mediaLabel}提示词`
    const cats=await promptApi.listCategories() as any[]
    let cat=cats.find((c:any)=>c.name===categoryName)
    if(!cat){cat=await promptApi.createCategory(categoryName) as any}
    // 保存提示词
    const name=text.slice(0,20)+(text.length>20?'…':'')
    await promptApi.create({name,content:isNegative?'':text,negative_content:isNegative?text:'',category_id:cat.id,remark:`从${typeInfo.value?.name||'生成'}页面添加`,tags:[]})
    notice.value=`已存入提示词库「${categoryName}」：${name}`
  }catch(e:any){notice.value=`保存失败：${typeof e==='string'?e:(e?.response?.data?.detail?String(e.response.data.detail):e?.message?String(e.message):'未知错误')}`}
  finally{savingPromptKey.value=null}
}

async function load(){
  saveLocalDraft();if(draftTimer)clearTimeout(draftTimer);draftReady=false;activeDraftCode=code.value;loading.value=true;notice.value='';rows.value.forEach(row=>release(row.outputs));rows.value=[]
  try{
    const [types,selectOptions]=await Promise.all([genTypeApi.list({enabled:true}),settingsApi.getSelectOptions()]);settings.value=selectOptions||{};typeInfo.value=(types as GenerationType[]).find(v=>v.code===code.value)||null
    if(!typeInfo.value)throw new Error('生成类型不存在或已停用')
    const [active,providers]=await Promise.all([generationTypeConfigApi.active(typeInfo.value.id),code.value==='mixed'?imageProviderApi.list():Promise.resolve([] as ImageProvider[])])
    config.value=active.config;published.value=active.published_version_id;runtimeWorkflows.value=(active.workflows||[]) as RuntimeWorkflow[];imageProviders.value=providers.filter(v=>v.enabled)
    if(code.value!=='mixed')executionTarget.value='comfyui'
    else if(!runtimeWorkflows.value.length&&imageProviders.value.length)executionTarget.value=`gemini:${(imageProviders.value.find(v=>v.is_default)||imageProviders.value[0]).id}`
    if(isMotion.value&&runtimeWorkflows.value.length&&!runtimeWorkflows.value.some(v=>v.parameter_schemes?.length)){const legacySchemes=config.value?.parameter_schemes?.length?config.value.parameter_schemes:await genTypeApi.motionTransferSchemes();runtimeWorkflows.value.forEach(v=>v.parameter_schemes=legacySchemes)}
    if(!restoreLocalDraft()){rows.value=[makeRow()];batchName.value=`${typeInfo.value.name}-${new Date().toLocaleString()}`}
    if(route.query.prompt&&rows.value[0]){if(usingGemini.value)rows.value[0].params.prompt=String(route.query.prompt);else{const schema=workflowFor(rows.value[0].workflowVersionId||defaultWorkflowVersion.value)?.parameters||[];const promptParam=schema.find(p=>p.type==='text'&&p.key.toLowerCase().includes('prompt')&&!p.key.toLowerCase().includes('negative'))||schema.find(p=>p.type==='textarea');if(promptParam)rows.value[0].params[promptParam.key]=String(route.query.prompt)}}
    if(!runtimeWorkflows.value.length&&code.value==='mixed'&&!imageProviders.value.length)notice.value='混合生图既没有可用工作流，也没有 Gemini Image 提供方。'
    else if(!runtimeWorkflows.value.length&&code.value!=='mixed')notice.value='当前生成类型还没有可用 ComfyUI 工作流。'
    const ids=String(route.query.resource_ids||route.query.resource_id||'').split(',').map(Number).filter(Boolean)
    if(ids.length){if(usingGemini.value){rows.value[0].params.reference_resource_ids=ids;notice.value=`已填入 ${ids.length} 张参考图片，将使用改图模式。`}else{const schema=workflowFor(defaultWorkflowVersion.value)?.parameters||[];const imgParam=schema.find(p=>p.type==='image');if(imgParam){rows.value[0].params[imgParam.key]=imgParam.multiple?ids:ids[0];notice.value=`已自动填入 ${ids.length} 张图片作为输入。`}}}
  }catch(e:any){typeInfo.value=null;notice.value=errorText(e)}finally{draftReady=true;loading.value=false}
}

async function createBatch(target:Row[],submit:boolean){if(!typeInfo.value)return null;for(const row of target){const message=validate(row);if(message)throw new Error(`第 ${rows.value.indexOf(row)+1} 行：${message}`)}const batch=await batchApi.create({name:batchName.value,generation_type_id:typeInfo.value.id,rows:target.map((row,index)=>({row_no:index,generation_type_id:typeInfo.value!.id,workflow_version_id:row.workflowVersionId,params:cleanParams(row)}))});for(const row of target)row.batchId=batch.id;if(!submit)return batch;const result=await batchApi.submit(batch.id);const tasks=await batchApi.rows(batch.id);target.forEach((row,index)=>{const task=tasks[index];row.taskId=task?.id||null;row.status=task?.status||'PENDING';row.error=task?.error||null});notice.value=`批次 #${batch.id} 已提交：${result.enqueued} 项进入队列${result.invalid?`，${result.invalid} 项无效`:''}`;startPoll();return batch}
async function submitAll(){submitting.value=true;try{await createBatch(rows.value,true)}catch(e:any){notice.value=errorText(e)}finally{submitting.value=false}}
async function submitOne(row:Row){submitting.value=true;try{await createBatch([row],true)}catch(e:any){notice.value=errorText(e)}finally{submitting.value=false}}
async function saveDraft(){submitting.value=true;try{const batch=await createBatch(rows.value,false);if(batch)notice.value=`草稿批次 #${batch.id} 已保存，可在批次任务中查看。`}catch(e:any){notice.value=errorText(e)}finally{submitting.value=false}}
async function refreshRows(){const pending=rows.value.filter(r=>r.taskId&&(activeStatuses.includes(r.status)||(r.status==='SUCCESS'&&!r.outputs.length)));await Promise.all(pending.map(async row=>{try{const task=await taskApi.get(row.taskId!);row.status=task.status;row.error=task.error;if(task.status==='SUCCESS'&&!row.outputs.length)await loadOutputs(row)}catch{}}));if(!busy.value&&!rows.value.some(r=>r.status==='SUCCESS'&&!r.outputs.length))stopPoll()}
async function loadOutputs(row:Row){if(!row.taskId)return;const list=await taskApi.outputs(row.taskId);release(row.outputs);row.outputs=await withThumbs(list)}
function startPoll(){if(!pollTimer)pollTimer=setInterval(()=>void refreshRows(),2000)}function stopPoll(){if(pollTimer){clearInterval(pollTimer);pollTimer=null}}
async function importPrompts(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const lines=(await file.text()).split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(!lines.length){notice.value='导入文件没有有效提示词';return}const added=lines.map(prompt=>{const row=makeRow();row.params.prompt=prompt;return row});rows.value=importMode.value==='replace'?added:[...rows.value,...added];notice.value=`已${importMode.value==='replace'?'替换为':'追加'} ${added.length} 条提示词，其他参数使用页面默认值。`;(event.target as HTMLInputElement).value=''}
watch([batchName,importMode,rows],()=>{if(!draftReady)return;if(draftTimer)clearTimeout(draftTimer);draftTimer=setTimeout(saveLocalDraft,250)},{deep:true})
watch(code,load);onMounted(()=>{window.addEventListener('beforeunload',saveLocalDraft);void load();connectWs();offWs=onWsEvent(()=>void refreshRows())});onBeforeUnmount(saveLocalDraft);onUnmounted(()=>{window.removeEventListener('beforeunload',saveLocalDraft);stopPoll();if(draftTimer)clearTimeout(draftTimer);offWs?.()})
</script>

<template>
  <div class="v2-page generate-page">
    <div class="v2-page-heading heading"><div><div class="eyebrow"><StatusBadge tone="info">动态配置</StatusBadge><StatusBadge :tone="published?'success':'warning'">{{ published?`已发布配置 #${published}`:'兼容配置' }}</StatusBadge></div><h1>{{ title }}</h1><p>{{ description }}</p></div><div class="heading-actions"><V2Button variant="ghost" @click="load">重新载入</V2Button><V2Button variant="primary" :disabled="submitting||loading||!rows.length" @click="submitAll">{{ submitting?'提交中…':`全部生成（${rows.length}）` }}</V2Button></div></div>
    <div v-if="notice" class="notice" :class="{danger:!typeInfo}">{{ notice }}</div>
    <GlassCard v-if="!loading&&typeInfo" padding="sm"><div class="batch-tools"><V2Field label="批次名称"><input v-model="batchName" /></V2Field><V2Field v-if="code==='mixed'" label="执行提供方"><select v-model="executionTarget" @change="switchExecutionTarget"><option v-if="runtimeWorkflows.length" value="comfyui">ComfyUI 工作流</option><option v-for="provider in imageProviders" :key="provider.id" :value="`gemini:${provider.id}`">{{ provider.name }} · {{ provider.model }}</option></select></V2Field><V2Field label="提示词导入方式"><select v-model="importMode"><option value="append">追加到现有任务行</option><option value="replace">清空后导入</option></select></V2Field><input ref="importInput" hidden type="file" accept=".txt,.csv,text/plain" @change="importPrompts"/><V2Button variant="ghost" @click="importInput?.click()">导入提示词</V2Button><V2Button variant="ghost" @click="addRow">新增任务行</V2Button><V2Button :disabled="submitting" @click="saveDraft">保存草稿</V2Button></div><small class="import-help">{{ code==='mixed'?'Gemini Image：不选择参考图即为生图，选择一张或多张参考图即为改图；结果统一进入素材库。':'此生成类型仅使用 ComfyUI 工作流。' }}</small></GlassCard>
    <div v-if="loading" class="loading-state">正在读取生成配置…</div>
    <div v-else class="rows"><GlassCard v-for="(row,index) in rows" :key="row.localId" padding="sm"><header class="row-head"><div><span class="row-no">{{ String(index+1).padStart(2,'0') }}</span><div><b>任务行 {{ index+1 }}</b><small v-if="row.taskId">任务 #{{ row.taskId }} · 批次 #{{ row.batchId }}</small><small v-else>尚未提交</small></div></div><div><StatusBadge :tone="statusMeta[row.status]?.tone||'neutral'">{{ statusMeta[row.status]?.label||row.status }}</StatusBadge><V2Button variant="ghost" @click="cloneRow(row)">复制</V2Button><V2Button variant="ghost" @click="removeRow(index)">删除</V2Button></div></header>
      <div class="row-body"><div class="parameter-grid">
        <template v-if="usingGemini"><V2Field label="图片尺寸" hint="选项来自系统维护项"><select v-model="row.params.size"><option v-if="!settings.image_size?.options?.length" value="">未维护图片尺寸</option><option v-for="option in settings.image_size?.options||[]" :key="option.value" :value="String(option.value)">{{ option.label }}</option></select></V2Field><V2Field label="参考图片" hint="可多选；留空为文生图，选择后为参考图改图" class="wide-field"><MediaParameterField v-model="row.params.reference_resource_ids" media-type="image" :multiple="true" :disabled="activeStatuses.includes(row.status)" /></V2Field><V2Field label="图片提示词" required class="wide-field"><div class="textarea-wrap"><textarea v-model="row.params.prompt" rows="5" :disabled="activeStatuses.includes(row.status)" placeholder="描述要生成的画面，或说明基于参考图需要修改的内容…"/></div></V2Field></template>
        <template v-else><V2Field label="工作流" required><select :value="row.workflowVersionId" :disabled="activeStatuses.includes(row.status)" @change="switchWorkflow(row,($event.target as HTMLSelectElement).value)"><option :value="null">请选择工作流</option><option v-for="workflow in runtimeWorkflows" :key="workflow.workflow_version_id" :value="workflow.workflow_version_id">{{ workflow.name }} · v{{ workflow.version }}</option></select></V2Field>
        <V2Field v-if="isMotion&&schemesFor(row).length" label="参数方案" required><select :value="row.params.__scheme" @change="applyScheme(row,($event.target as HTMLSelectElement).value)"><option v-for="scheme in schemesFor(row)" :key="scheme.id" :value="scheme.id">{{ scheme.name }}{{ scheme.is_default?'（默认）':'' }}</option></select></V2Field>
        <V2Field v-if="hasSize(row)&&sizeSetting" :label="outputMediaType==='video'?'视频尺寸':'图片尺寸'"><select :value="row.params.__size" @change="setSize(row,($event.target as HTMLSelectElement).value)"><option v-for="option in sizeSetting.options" :key="option.value" :value="option.value">{{ option.label }}</option></select></V2Field>
        <template v-for="parameter in visibleParameters(row)" :key="parameter.key"><V2Field v-if="visible(parameter,row)" :label="parameter.label||parameter.key" :hint="parameter.help||(parameter.unit?`单位：${parameter.unit}`:undefined)" :required="parameter.required" :class="{'wide-field':['textarea','image','video','audio'].includes(parameter.type)}">
          <div v-if="parameter.type==='textarea'" class="textarea-wrap"><textarea v-model="row.params[parameter.key]" rows="3" :disabled="activeStatuses.includes(row.status)" /><button v-if="parameter.key.toLowerCase().includes('prompt')" type="button" class="save-prompt-btn" :disabled="savingPromptKey===parameter.key||activeStatuses.includes(row.status)" @click="saveToPromptLib(row,parameter)">{{ savingPromptKey===parameter.key?'保存中…':'存入提示词库' }}</button></div>
          <select v-else-if="parameter.type==='select'||parameter.type==='size'" v-model="row.params[parameter.key]" :disabled="activeStatuses.includes(row.status)"><option v-for="option in optionList(parameter)" :key="String(option.value)" :value="option.value">{{ option.label }}</option></select>
          <label v-else-if="parameter.type==='bool'" class="switch"><input v-model="row.params[parameter.key]" type="checkbox" :disabled="activeStatuses.includes(row.status)"/><span/><b>{{ row.params[parameter.key]?'已开启':'已关闭' }}</b></label>
          <MediaParameterField v-else-if="['image','video','audio'].includes(parameter.type)" v-model="row.params[parameter.key]" :media-type="parameter.type as 'image'|'video'|'audio'" :multiple="parameter.multiple" :disabled="activeStatuses.includes(row.status)" :mask-resource-id="parameter.type==='image'?(row.params[parameter.key+'__mask']||null):undefined" @update:mask-resource-id="parameter.type==='image'?(row.params[parameter.key+'__mask']=$event):undefined" />
          <div v-else-if="parameter.type==='seed'" class="seed-input"><input v-model.number="row.params[parameter.key]" type="number"/><V2Button variant="ghost" @click="row.params[parameter.key]=randomSeed()">随机</V2Button></div>
          <input v-else :value="row.params[parameter.key]" :type="['int','float','slider'].includes(parameter.type)?'number':'text'" :min="parameter.min" :max="parameter.max" :step="parameter.step||(parameter.type==='int'?1:'any')" :disabled="activeStatuses.includes(row.status)" @input="row.params[parameter.key]=['int','float','slider'].includes(parameter.type)?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value"/>
        </V2Field></template></template>
      </div><aside class="result"><div class="result-head"><b>执行结果</b><span v-if="row.error">{{ row.error }}</span><span v-else>{{ statusMeta[row.status]?.label||'等待生成' }}</span></div><div v-if="row.outputs.length" class="output-grid"><button v-for="output in row.outputs" :key="output.id" @click="preview=output"><img v-if="output.media_type==='image'||output.media_type==='video'" :src="output.thumbUrl"/><span v-else-if="output.media_type==='audio'">♪</span><span v-else-if="output.media_type==='text'" class="text-ic">文</span><span v-else>▧</span><i v-if="output.media_type==='video'">▶</i></button></div><div v-else class="empty-output"><span>{{ outputMediaType==='image'?'▧':outputMediaType==='video'?'▶':'♪' }}</span><small>{{ activeStatuses.includes(row.status)?'任务执行中，结果会自动刷新':'生成结果将在这里显示' }}</small></div><V2Button variant="primary" :disabled="submitting||activeStatuses.includes(row.status)" @click="submitOne(row)">生成此项</V2Button></aside></div>
    </GlassCard></div>
    <MediaViewer :open="!!preview" :output="preview" @close="preview=null"/>
  </div>
</template>

