;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:9px;cursor:pointer}.output-grid img{width:100%;height:100%;object-fit:contain}.output-grid i{position:absolute;inset:0;display:grid;place-items:center;font-size:24px;text-shadow:0 2px 4px #000}.switch{height:42px;padding:0 11px;display:flex;align-items:center;gap:9px;background:rgba(3,12,25,.42);border:1px solid var(--v2-border);border-radius:10px}.switch input{display:none}.switch span{width:34px;height:19px;padding:2px;background:#536176;border-radius:20px}.switch span:after{content:'';display:block;width:15px;height:15px;background:white;border-radius:50%;transition:.2s}.switch input:checked+span{background:var(--v2-primary)}.switch input:checked+span:after{transform:translateX(15px)}.switch b{font-size:12px}.seed-input{display:grid;grid-template-columns:1fr auto;gap:7px}
